 class Student
{
    // حقول خاصة
    private string name;
    private int age;
    private int grade;

    // منشئ
    public Student(string name, int age, int grade)
    {
        SetName(name);
        SetAge(age);
        SetGrade(grade);
    }

    // وصول يدوي
    public string GetName() { return name; }
    public void SetName(string name)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new ArgumentException("Name cannot be empty.");
        this.name = name;
    }

    public int GetAge() { return age; }
    public void SetAge(int age)
    {
        if (age < 0) throw new ArgumentException("Age must be non-negative.");
        this.age = age;
    }

    public int GetGrade() { return grade; }
    public void SetGrade(int grade)
    {
        if (grade < 0 || grade > 100)
            throw new ArgumentException("Grade must be 0..100.");
        this.grade = grade;
    }

    // سلوك
    public void PrintInfo()
    {
        Console.WriteLine($"{GetName()} - Age: {GetAge()}, Grade: {GetGrade()}");
    }
}

static void Main(string[] args)
{
    Student[] students = new Student[3];
    students[0] = new Student("Lina", 16, 95);
    students[1] = new Student("Omar", 17, 82);
    students[2] = new Student("Rana", 16, 90);
    // حساب المتوسط باستخدام GetGrade()
    int sum = 0;
    for (int i = 0; i < students.Length; i++)
    {
        if (students[i] != null)
            sum += students[i].GetGrade();
    }
    double avg = (double)sum / students.Length;
    Console.WriteLine($"Average: {avg}");
}

    class Classroom
    {
        private Student[] students;
        private int count = 0;

        public Classroom(int capacity)
        {
            students = new Student[capacity];
        }

        public void AddStudent(Student s)
        {
            if (count < students.Length)
                students[count++] = s;
            else
                Console.WriteLine("Classroom is full!");
        }

        public double Average()
        {
            if (count == 0) return 0;
            int sum = 0;
            for (int i = 0; i < count; i++)
                sum += students[i].GetGrade();
            return (double)sum / count;
        }
        public Student TopStudent()
        {
            if (count == 0) return null;
            Student best = students[0];
            for (int i = 1; i < count; i++)
                if (students[i].GetGrade() > best.GetGrade())
                    best = students[i];
            return best;
        }
}
static void Main(string[] args)
{
    var cls = new Classroom(5);
    cls.AddStudent(new Student("Lina", 16, 95));
    cls.AddStudent(new Student("Omar", 17, 82));
    Console.WriteLine($"Class Avg: {cls.Average()}");
    Console.WriteLine($"Top: {cls.TopStudent().GetName()}");

}

class Course
{
    private double[] grades;

    public Course(double[] grades)
    {
        this.grades = grades ?? Array.Empty<double>();
    }

    public double Min()
    {
        if (grades.Length == 0) return 0;
        double m = grades[0];
        for (int i = 1; i < grades.Length; i++)
            if (grades[i] < m) m = grades[i];
        return m;
    }

    public double Max()
    {
        if (grades.Length == 0) return 0;
        double m = grades[0];
        for (int i = 1; i < grades.Length; i++)
            if (grades[i] > m) m = grades[i];
        return m;
    }
}

